// Settings → About → "Third-party licences" (SPEC 10.4): every component this build ships,
// generated by scripts/third_party.py, plus the full texts in THIRD-PARTY-NOTICES.txt.
import { useQuery } from "@tanstack/react-query";
import { useState } from "react";
import { useTranslation } from "react-i18next";
import { Modal } from "../../components/Modal";
import { errorMessage } from "../../lib/errors";
import {
  openThirdPartyNotices,
  type ThirdPartyPackage,
  thirdPartyLicenses,
} from "../../lib/system";

const ORDER: readonly ThirdPartyPackage["component"][] = [
  "bundled",
  "engine",
  "core",
  "app",
  "download",
];

function matches(p: ThirdPartyPackage, query: string): boolean {
  const q = query.trim().toLowerCase();
  return !q || p.name.toLowerCase().includes(q) || p.license.toLowerCase().includes(q);
}

function Group({
  component,
  packages,
}: {
  component: ThirdPartyPackage["component"];
  packages: ThirdPartyPackage[];
}) {
  const { t } = useTranslation();
  const label = t(`licenses.components.${component}`);
  return (
    <section aria-label={label} className="flex flex-col gap-1">
      <h3 className="flex items-baseline gap-2 text-label uppercase text-text-3">
        {label}
        <span className="font-mono normal-case">{packages.length}</span>
      </h3>
      <ul className="flex flex-col">
        {packages.map((p) => (
          <li
            key={`${p.name}@${p.version}`}
            className="flex flex-col gap-0.5 border-b border-border py-1.5 last:border-b-0"
          >
            <div className="flex items-baseline justify-between gap-3">
              <span className="min-w-0 truncate text-control text-text">
                {p.name}
                {p.version && (
                  <span className="ml-2 font-mono text-[11px] text-text-3">{p.version}</span>
                )}
              </span>
              <span className="shrink-0 text-right font-mono text-[11px] text-text-2">
                {p.license}
              </span>
            </div>
            {p.note && (
              <span className="text-control text-text-2">{t(`licenses.notes.${p.note}`)}</span>
            )}
          </li>
        ))}
      </ul>
    </section>
  );
}

export function ThirdPartyDialog({ onClose }: { onClose: () => void }) {
  const { t } = useTranslation();
  const [query, setQuery] = useState("");
  const listing = useQuery({
    queryKey: ["third-party-licenses"],
    queryFn: thirdPartyLicenses,
    staleTime: Infinity,
    retry: false,
  });
  const packages = listing.data?.packages ?? [];
  const shown = packages.filter((p) => matches(p, query));

  return (
    <Modal label={t("licenses.title")} onClose={onClose} width={720}>
      <header className="flex items-center justify-between border-b border-border px-5 py-4">
        <h2 className="font-display text-title">{t("licenses.title")}</h2>
        <button
          type="button"
          onClick={onClose}
          className="h-8 rounded-sm border border-border bg-surface-3 px-3 text-text"
        >
          {t("toast.dismiss")}
        </button>
      </header>
      <div className="flex min-h-0 flex-1 flex-col gap-5 overflow-auto px-5 py-4">
        {listing.isError ? (
          <p role="alert" className="text-body text-warning">
            {errorMessage(listing.error)}
          </p>
        ) : listing.isPending ? (
          <p className="text-body text-text-3">{t("licenses.loading")}</p>
        ) : (
          <>
            <p className="text-body text-text-2">
              {t("licenses.intro", { count: packages.length })}
            </p>
            <input
              type="search"
              data-autofocus
              value={query}
              onChange={(e) => setQuery(e.target.value)}
              aria-label={t("licenses.search")}
              placeholder={t("licenses.search")}
              className="h-8 shrink-0 rounded-sm border border-border bg-surface-3 px-3 text-control text-text placeholder:text-text-3"
            />
            {shown.length === 0 && <p className="text-body text-text-3">{t("licenses.noMatch")}</p>}
            {ORDER.map((component) => {
              const group = shown.filter((p) => p.component === component);
              return group.length > 0 ? (
                <Group key={component} component={component} packages={group} />
              ) : null;
            })}
            {!query && (listing.data?.acknowledgements.length ?? 0) > 0 && (
              <section aria-labelledby="licenses-acks" className="flex flex-col gap-2">
                <h3 id="licenses-acks" className="text-label uppercase text-text-3">
                  {t("licenses.acksTitle")}
                </h3>
                <ul className="flex list-disc flex-col gap-1.5 pl-5 text-control text-text-2">
                  {listing.data?.acknowledgements.map((a) => (
                    <li key={a.key}>{t(`licenses.acks.${a.key}`)}</li>
                  ))}
                </ul>
              </section>
            )}
          </>
        )}
      </div>
      <footer className="flex items-center gap-3 border-t border-border px-5 py-3">
        <button
          type="button"
          disabled={!listing.isSuccess}
          onClick={() => void openThirdPartyNotices().catch(() => undefined)}
          className="h-8 rounded-sm border border-border bg-surface-3 px-3 text-text hover:border-border-strong disabled:opacity-50"
        >
          {t("licenses.openTexts")}
        </button>
        <span className="text-control text-text-3">{t("licenses.textsHint")}</span>
      </footer>
    </Modal>
  );
}
